import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
OUT = "/tmp/recon"

token = None
events = {"401_refresh": 0, "429_wait": 0, "5xx_retry": 0, "net_retry": 0, "404": 0}
logged_429 = 0


def log(*a):
    print(*a, file=sys.stderr, flush=True)


def get_token():
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)["token"]


def retry_after_seconds(headers, body):
    ra = headers.get("Retry-After")
    if ra is not None:
        try:
            return float(ra)
        except ValueError:
            pass
    try:
        data = json.loads(body)
        for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
            if key in data:
                return float(data[key])
    except (ValueError, TypeError, AttributeError):
        pass
    return None


class NotFound(Exception):
    pass


def api(path, auth=True, max_attempts=500):
    global token, logged_429
    attempt = 0
    while True:
        attempt += 1
        if attempt > max_attempts:
            raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")
        headers = {}
        if auth:
            if token is None:
                token = get_token()
            headers["Authorization"] = "Bearer " + token
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.loads(r.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            code = e.code
            if code == 401:
                events["401_refresh"] += 1
                log(f"401 on {path}: {body[:200]!r}; refreshing token")
                token = get_token()
                continue
            if code == 429 or code == 503:
                wait = retry_after_seconds(e.headers, body)
                if logged_429 < 3:
                    log(f"{code} on {path}: headers={dict(e.headers)} body={body[:300]!r}")
                    logged_429 += 1
                if wait is None:
                    wait = 2.0
                events["429_wait"] += 1
                time.sleep(wait + 0.5)
                continue
            if code == 404:
                events["404"] += 1
                raise NotFound(path)
            if code >= 500:
                events["5xx_retry"] += 1
                log(f"{code} on {path}: {body[:200]!r}; retrying")
                time.sleep(min(2 ** min(attempt, 6), 60))
                continue
            raise RuntimeError(f"{code} on {path}: {body[:300]!r}")
        except (urllib.error.URLError, TimeoutError, ConnectionError, json.JSONDecodeError) as e:
            events["net_retry"] += 1
            log(f"network/parse error on {path}: {e!r}; retrying")
            time.sleep(min(2 ** min(attempt, 6), 60))
            continue


def main():
    # 1. Walk the order listing by following "next" links, checking the page
    #    number and total_pages as we go.
    pages = []
    path = "/orders?page=1"
    expected = 1
    while path is not None:
        data = api(path)
        if data["page"] != expected:
            raise RuntimeError(f"expected page {expected}, got {data['page']} from {path}")
        pages.append({"path": path, "page": data["page"], "total_pages": data["total_pages"],
                      "next": data["next"], "items": data["items"]})
        log(f"page {data['page']}/{data['total_pages']}: {len(data['items'])} items, next={data['next']}")
        path = data["next"]
        expected += 1

    total_pages = pages[0]["total_pages"]
    if len(pages) != total_pages:
        raise RuntimeError(f"walked {len(pages)} pages but total_pages={total_pages}")
    with open(f"{OUT}/pages.json", "w") as f:
        json.dump(pages, f)

    # 2. Fetch every customer referenced by a listed order, once each.
    customer_ids = sorted({o["customer_id"] for p in pages for o in p["items"]})
    customers = {}
    missing = []
    for cid in customer_ids:
        try:
            customers[cid] = api(f"/customers/{cid}")
        except NotFound:
            missing.append(cid)
    log(f"customers fetched: {len(customers)}, missing: {missing}")
    with open(f"{OUT}/customers.json", "w") as f:
        json.dump({"customers": customers, "missing": missing}, f)

    log("events:", events)


if __name__ == "__main__":
    main()

